"use client";

import { useEffect, useState } from "react";

/**
 * Live server clock (display only). The offset between the backend clock and this device is measured with
 * GET /api/attendance/server-time and re-measured every minute, so a wrong laptop / mobile clock does not
 * change what is shown. Official attendance times are always generated by the backend.
 */
let offsetMs: number | null = null;
let status: "syncing" | "synced" | "offline" = "syncing";
let lastSync = 0;
let inflight: Promise<void> | null = null;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach(l => l());

export async function syncServerClock(): Promise<void> {
    if (inflight) return inflight;
    inflight = (async () => {
        try {
            const t0 = Date.now();
            const r = await fetch("/api/attendance/server-time", { cache: "no-store" });
            const t1 = Date.now();
            if (!r.ok) throw new Error(String(r.status));
            const d = await r.json();
            const server = Date.parse(d.serverTime);
            if (isNaN(server)) throw new Error("bad time");
            offsetMs = server + (t1 - t0) / 2 - t1; // half the round trip
            status = "synced"; lastSync = t1;
        } catch {
            status = "offline"; lastSync = Date.now() - 50000; // try again in about 10 s
        } finally { inflight = null; emit(); }
    })();
    return inflight;
}

/** Server time now, or null while it has never been synced (nothing is made up) */
export const serverNow = (): Date | null => (offsetMs === null ? null : new Date(Date.now() + offsetMs));

const IST = "Asia/Kolkata";
/** YYYY-MM-DD in IST */
export const istDate = (d: Date) => d.toLocaleDateString("en-CA", { timeZone: IST });
/** HH:MM (24 h) in IST */
export const istHHMM = (d: Date) => d.toLocaleTimeString("en-GB", { timeZone: IST, hour: "2-digit", minute: "2-digit", hour12: false });
/** HH:MM:SS (24 h) in IST */
export const istHHMMSS = (d: Date) => d.toLocaleTimeString("en-GB", { timeZone: IST, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
/** "Wednesday, 14 October 2026" (same on every browser) */
export const istLongDate = (d: Date) => {
    const p = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: IST, weekday: "long", day: "numeric", month: "long", year: "numeric" })
        .formatToParts(d).map(x => [x.type, x.value]));
    return `${p.weekday}, ${p.day} ${p.month} ${p.year}`;
};
export const istClock = (d: Date, seconds = false) => d.toLocaleTimeString("en-US", { timeZone: IST, hour: "2-digit", minute: "2-digit", ...(seconds ? { second: "2-digit" } : {}), hour12: true });

/** Re-renders every second with the server time; re-syncs every 60 s (and when the tab comes back) */
export function useServerClock() {
    const [, setTick] = useState(0);
    useEffect(() => {
        const l = () => setTick(t => t + 1);
        listeners.add(l);
        if (offsetMs === null || Date.now() - lastSync > 60000) syncServerClock();
        const tick = setInterval(() => {
            if (Date.now() - lastSync > 60000) syncServerClock();
            setTick(t => t + 1);
        }, 1000);
        const vis = () => { if (document.visibilityState === "visible") syncServerClock(); };
        document.addEventListener("visibilitychange", vis);
        return () => { listeners.delete(l); clearInterval(tick); document.removeEventListener("visibilitychange", vis); };
    }, []);
    return { now: serverNow(), status };
}